(() => {
  const presets=[window.shopPricing.minimumRobuxQuantity,800,1700,4500,10000,22500];
  const min=window.shopPricing.minimumRobuxQuantity,max=22500;
  const money=value=>value.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
  const number=value=>value.toLocaleString('pt-BR');
  const clamp=value=>Math.max(min,Math.min(max,Math.round(Number(value)||min)));
  const prices=value=>{const price=window.shopPricing.robux(value),reference=Math.round(value*6.25)/100;return {price,reference,saving:Math.round((reference-price)*100)/100}};
  let quantity=1000,observer=null,userPaused=false,coin=null,coinVisible=true,priceAnimation=null;
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
  const faq=[['Qual é o prazo de entrega?','Na loja original, o prazo informado é de 24h a 48h úteis. Via Gamepass, o repasse também pode depender do prazo do Roblox. Confira o método e as instruções antes de comprar.'],['Como recebo meu pedido?','Escolha Via Gift Card para criar um cartão personalizado com o pacote selecionado ou continue via Roblox Plus. Esta recriação permite montar o pedido, sem realizar pagamentos nem entregas.'],['A taxa do Roblox está incluída?','A referência informa que não cobre a taxa do Roblox. Confira o valor bruto e o que será recebido conforme o método. A calculadora desta página mostra valores de referência, não uma cotação ao vivo.'],['A loja pede minha senha Roblox?','Não. Informe somente seu nome de usuário. Nunca forneça senha, cookie ou token para consultar um perfil público.']];
  const guide=[['O que é Robux?','É a moeda virtual utilizada na plataforma Roblox para itens, acessórios e benefícios em experiências compatíveis.'],['Como escolher seu pacote?','Use os atalhos ou ajuste a quantidade. Compare o total e o valor de referência antes de continuar.'],['Gift Card ou Roblox Plus?','Gift Card cria uma prévia personalizada com a quantidade e o preço selecionados. Roblox Plus permite selecionar um pacote de Robux. Confira as condições do método antes de continuar.'],['O que significa a taxa do Roblox?','Uma venda de Gamepass pode ter uma dedução aplicada pela plataforma. O valor bruto do passe não é necessariamente o saldo líquido recebido.'],['Por que os Robux podem ficar pendentes?','O Roblox pode manter valores de vendas pendentes antes de liberar o saldo. Esse prazo é controlado pela plataforma.'],['Preciso informar minha senha?','Não. A seleção de perfil utiliza dados públicos e não concede acesso à sua conta Roblox.'],['O que conferir antes de continuar?','Confira quantidade, preço, método e nome de usuário. Esta versão não cobra pagamentos nem cria pedidos reais.']];
  function page(products=[]){const m=window.originalMedia||{};const raw=new URLSearchParams(location.search).get('qty');quantity=raw&&/^\d+$/.test(raw)?clamp(raw):1000;const p=prices(quantity);return `<div class="rx-page"><div class="wrap rx-breadcrumb breadcrumb"><a href="/">Início</a> › <a href="/loja">Loja</a> › <a href="/robux">Robux</a> › Escolha sua quantidade</div><section class="wrap rx-main" id="rx-purchase"><div class="rx-visual"><div class="rx-orbit-lines" aria-hidden="true"></div><div class="rx-coin-scene" role="group" aria-label="Robux em 3D interativo"><div class="rx-coin">${Array.from({length:15},(_,i)=>`<img class="rx-coin-layer" src="/assets/robux-coin-face.svg" alt="" style="--depth:${i*3-21}px" draggable="false">`).join('')}<img class="rx-coin-front" src="/assets/robux-coin-face.svg" alt="" draggable="false"><img class="rx-coin-back" src="/assets/robux-coin-face.svg" alt="" draggable="false"></div></div></div><div class="rx-config"><h1>Compre <em>Robux</em><br>com mais economia</h1><p class="rx-intro">Escolha seu pacote e confira o valor antes de continuar. Tudo sem precisar informar sua senha Roblox.</p><div class="rx-price-panel"><div><small>VOCÊ PAGA</small><strong id="rx-price">${money(p.price)}</strong><p>Não cobrimos a taxa do Roblox. <a href="#rx-guide-3">Saiba mais</a></p></div><div class="rx-savings"><small>VOCÊ ECONOMIZA</small><b id="rx-saving">${money(p.saving)}</b><del id="rx-reference">No Roblox: ${money(p.reference)}</del></div></div><div class="methods rx-methods"><button class="method" data-rx-gift>VIA GIFT CARD<small>Criar com o valor selecionado</small></button><button class="method" aria-pressed="true">ROBLOX PLUS<small>R$ 25,55 / 1k</small></button></div><div class="rx-package-label"><b>Escolha seu pacote de Robux</b><p>Escolha um pacote ou ajuste na barra. Valor mínimo: R$ 15,00.</p></div><div class="rx-quantity"><button data-rx-minus aria-label="Diminuir quantidade">−</button><label class="sr-only" for="rx-quantity">Quantidade de Robux</label><input id="rx-quantity" inputmode="numeric" type="number" min="${min}" max="${max}" step="1" value="${quantity}"><button data-rx-plus aria-label="Aumentar quantidade">+</button></div><label class="sr-only" for="rx-range">Ajustar quantidade de Robux</label><input id="rx-range" class="rx-range" type="range" min="${min}" max="${max}" step="1" value="${quantity}" style="--fill:${(quantity-min)/(max-min)*100}%"><div class="rx-range-labels"><span>${min}</span><span>22.500</span></div><div class="rx-presets">${presets.map((n,i)=>`<button data-rx-qty="${n}" aria-pressed="${quantity===n}"><img src="/assets/original/95f42cfc9a9a702b.png" alt=""><span>${[String(min),'800','1,7K','4,5K','10K','22,5K'][i]}</span></button>`).join('')}</div><p id="rx-error" class="rx-error" role="alert"></p><div class="rx-trust"><div>♢ <b>SEM SENHA</b><small>Somente o nome de usuário</small></div><div>◇ <b>VALOR CLARO</b><small>Confira antes de continuar</small></div><div>◉ <b>SEU PERFIL</b><small>Seleção salva no navegador</small></div></div><button class="button rx-buy" data-rx-buy>COMPRAR ROBUX AGORA →</button><button class="rx-add" data-rx-add>♧ Adicionar ao carrinho</button><small class="rx-price-note">Valores de referência da recriação · sem pagamento real</small></div></section>
  ${window.reviewWall?.page()||''}
  <section class="rx-faq"><div class="wrap faq"><h2>Dúvidas antes de <em>comprar?</em></h2><p>Entenda os métodos, os valores e as informações do pedido.</p>${faq.map(([q,a])=>`<details><summary>${q}</summary><div class="faq-answer"><p>${a}</p></div></details>`).join('')}</div></section>
  <section class="rx-guide"><div class="wrap"><span class="eyebrow">GUIA</span><h2>Guia rápido sobre <em>Robux</em></h2><p>O que considerar antes de escolher sua quantidade.</p><div class="guide"><aside>${guide.map(([q],i)=>`<a href="#rx-guide-${i}">${q}</a>`).join('')}</aside><div>${guide.map(([q,a],i)=>`<article id="rx-guide-${i}"><h3>${q}</h3><p>${a}</p></article>`).join('')}<a class="button" href="#rx-purchase">ESCOLHER MEU PACOTE ↑</a></div></div></div></section>
  <section class="rx-showcase"><div class="wrap"><span class="eyebrow">VITRINE STARBUXX</span><div class="rx-showcase-heading"><h2>Os mais procurados<br>pela comunidade</h2><a href="/loja" class="landing-outline">VER LOJA COMPLETA ↗</a></div><p>Explore também frutas, gamepasses e itens dos seus jogos.</p><div class="rx-showcase-list">${[0,9,10,8,14,18].map(id=>{const product=products[id];if(!product)return '';return `<article class="rx-product"><button class="rx-product-image" data-product="${id}" aria-label="Ver ${product.name}"><img src="${m.products?.[id]||'/assets/'+product.art+'.svg'}" alt="${product.name}" loading="lazy"></button><h3>${product.name}</h3><b>${money(product.price)}</b><button class="button" data-product="${id}">COMPRAR AGORA</button></article>`}).join('')}</div></div></section></div>`}
  function sync(){const p=prices(quantity);const input=document.querySelector('#rx-quantity');if(input)input.value=quantity;const slider=document.querySelector('#rx-range');if(slider){slider.value=quantity;slider.style.setProperty('--fill',(quantity-min)/(max-min)*100+'%')}const priceNode=document.querySelector('#rx-price');const changed=priceNode.textContent!==money(p.price);priceNode.textContent=money(p.price);if(changed&&!reduced.matches&&priceNode.animate){priceAnimation?.cancel();priceAnimation=priceNode.animate([{opacity:.4,transform:'translateY(5px)'},{opacity:1,transform:'none'}],{duration:180,easing:'ease-out'})}document.querySelector('#rx-saving').textContent=money(p.saving);document.querySelector('#rx-reference').textContent='No Roblox: '+money(p.reference);document.querySelectorAll('[data-rx-qty]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.rxQty)===quantity)));document.querySelector('#rx-error').textContent='';}
  function valid(){const input=document.querySelector('#rx-quantity');if(!input||!input.checkValidity()){input?.reportValidity();return false}quantity=clamp(input.value);return true}
  let giftQuantity=1000;
  function createGiftCard(value){giftQuantity=clamp(value);const price=prices(giftQuantity).price;window.lojaCart?.open(`<div class="rx-gift-preview"><span class="eyebrow">SEU GIFT CARD</span><h2>Gift Card personalizado</h2><p>Quantidade e valor conforme sua seleção.</p><div class="rx-custom-card"><span class="rx-card-type">GIFT CARD · STARBUXX</span><img class="rx-card-wordmark" src="/assets/roblox-wordmark.svg?v=2" alt="Roblox"><img class="rx-card-symbol" src="/assets/original/570507b5e2ef9723.svg" alt=""><strong>${number(giftQuantity)} <small>ROBUX</small></strong><div><span>VALOR DO PEDIDO</span><b>${money(price)}</b></div></div><button class="button" data-rx-gift-buy>Continuar compra · ${money(price)}</button><button class="rx-add" data-rx-gift-add>Adicionar Gift Card ao carrinho</button><p class="co-local">Prévia demonstrativa. Esta versão não emite código oficial de resgate.</p></div>`)}
  function addGift(checkout=false){window.lojaCart?.addRobux({quantity:giftQuantity,method:'giftcard'});if(checkout)window.lojaCart?.checkout();else window.lojaCart?.showCart()}
  function checkout(){if(!valid())return;add();window.lojaCart?.checkout();}
  function add(){if(!valid())return;window.lojaCart?.addRobux({quantity,method:'plus'});}
  function cleanup(){window.robux3D?.dispose();observer?.disconnect();observer=null;priceAnimation?.cancel();priceAnimation=null;coin=null;}
  function mount(){cleanup();coin=document.querySelector('.rx-coin');if(!coin)return;userPaused=false;coinVisible=true;coin.classList.toggle('rx-reduced',reduced.matches);if(window.IntersectionObserver){observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{coinVisible=isIntersecting;target.classList.toggle('rx-offscreen',!isIntersecting||document.hidden)}),{threshold:.1});observer.observe(coin)}sync();window.robux3D?.mount(coin);}
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-rx-minus')){quantity=clamp(quantity-10);sync()}if(b.hasAttribute('data-rx-plus')){quantity=clamp(quantity+10);sync()}if(b.hasAttribute('data-rx-qty')){quantity=Number(b.dataset.rxQty);sync()}if(b.hasAttribute('data-rx-gift')){if(valid())createGiftCard(quantity)}if(b.hasAttribute('data-rx-gift-add'))addGift();if(b.hasAttribute('data-rx-gift-buy'))addGift(true);if(b.hasAttribute('data-rx-buy'))checkout();if(b.hasAttribute('data-rx-add'))add();if(b.hasAttribute('data-rx-confirm-add')){add();window.lojaCart?.showCart()}});
  document.addEventListener('input',event=>{if(event.target.id==='rx-range'){quantity=clamp(event.target.value);sync()}if(event.target.id==='rx-quantity'){const raw=Number(event.target.value);if(Number.isInteger(raw)&&raw>=min&&raw<=max){quantity=raw;const input=event.target;const start=input.selectionStart;sync();try{if(start!==null)input.setSelectionRange(start,start)}catch{}}}});
  document.addEventListener('change',event=>{if(event.target.id==='rx-quantity'){quantity=clamp(event.target.value);sync()}});
  document.addEventListener('visibilitychange',()=>coin?.classList.toggle('rx-offscreen',document.hidden||!coinVisible));
  reduced.addEventListener('change',()=>coin?.classList.toggle('rx-reduced',reduced.matches));window.addEventListener('pagehide',cleanup);
  window.robuxPage={page,mount,clamp,prices,createGiftCard};
})();
